    "question": "An acidic buffer is prepared by mixing a weak monoprotic acid (pK_a = 3.5) and its conjugate salt such that [Conjugate Base] / [Acid] = 0.1. What is the resulting pH of the buffer solution?",
    "options": [
      "2.50",
      "3.50",
      "1.50",
      "7.00"
    ],
    "answer": 0,
    "explanation": "By Henderson-Hasselbalch equation: pH = pK_a + \\log\\left(\\frac{[\\text{Salt}]}{[\\text{Acid}]}\\right) = 3.5 + \\log_{10}(0.1) = 2.50.",
