    "question": "The vapor pressure of pure liquid solvent at 298 K is P^\\circ = 40 mm Hg. A non-volatile solute is dissolved to form an ideal solution with solute mole fraction X_{solute} = 0.1. What is the vapor pressure P of the resulting solution?",
    "options": [
      "36.00 mm Hg",
      "4.00 mm Hg",
      "40 mm Hg",
      "44.00 mm Hg"
    ],
    "answer": 0,
    "explanation": "By Raoult’s law: P = P^\\circ \\cdot X_{solvent} = P^\\circ (1 - X_{solute}) = 40 \\times (1 - 0.1) = 40 - 4.00 = 36.00 \\, \\text{mm Hg}.",
